import sqlite3
import requests
import stripe

REGISTRY_URL = "https://registry.internal.example.com/v1"
DB_PATH = "domains.db"


def transfer_domain_to_registrar(domain, auth_code, gaining_registrar, fee_cents):
    if not domain or "." not in domain:
        return {"ok": False, "error": "invalid domain"}
    if not auth_code:
        return {"ok": False, "error": "auth_code required"}
    if not gaining_registrar:
        return {"ok": False, "error": "gaining_registrar required"}
    if fee_cents is None or fee_cents < 0:
        return {"ok": False, "error": "invalid fee"}

    domain = domain.strip().lower()
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute("SELECT locked FROM active_domains WHERE name = ?", (domain,)).fetchone()
    if row is None:
        conn.close()
        return {"ok": False, "error": "domain not found"}
    if row[0]:
        conn.close()
        return {"ok": False, "error": "domain is locked"}

    charge = stripe.PaymentIntent.create(
        amount=fee_cents,
        currency="usd",
        description=f"Transfer out {domain}",
        confirm=True,
        payment_method="pm_card_default",
    )
    resp = requests.post(
        f"{REGISTRY_URL}/domains/{domain}/transfer",
        json={"auth_code": auth_code, "gaining_registrar": gaining_registrar},
        timeout=30,
    )
    if resp.status_code != 200:
        conn.close()
        return {"ok": False, "error": resp.text, "charge_id": charge.id}

    conn.execute("INSERT INTO transferring_out SELECT * FROM active_domains WHERE name = ?", (domain,))
    conn.execute("DELETE FROM active_domains WHERE name = ?", (domain,))
    conn.commit()
    conn.close()
    return {"ok": True, "charge_id": charge.id}
